def retry_with_backoff(operation, max_retries, base_delay, max_delay, jitter, idempotency_key=None):
    for attempt in range(max_retries + 1):
        try:
            return operation()
        except Exception:
            if attempt == max_retries:
                raise
            delay = min(max_delay, base_delay * 2**attempt)
            sleep(delay + random.uniform(0, jitter))

